CREATE TABLE key_subsidies(owner TEXT PRIMARY KEY NOT NULL,state INTEGER NOT NULL DEFAULT 0 CHECK(state IN (0,1,2)),token TEXT,attached INTEGER NOT NULL DEFAULT 0 CHECK(attached>=0 AND attached<=30000000000),actual INTEGER CHECK(actual>=0 AND actual<=attached),CHECK(state=0 OR token IS NOT NULL),CHECK(state<>2 OR (actual IS NOT NULL AND actual>0)));
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_INSERT_size BEFORE INSERT ON key_subsidies WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+24)>256 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_UPDATE_size BEFORE UPDATE ON key_subsidies WHEN (4+length(CAST(NEW.owner AS BLOB))+4+length(CAST(NEW.token AS BLOB))+24)>256 OR length(CAST(NEW.owner AS BLOB))>63 OR length(CAST(NEW.token AS BLOB))>128 BEGIN SELECT RAISE(ABORT,'accounting row capacity'); END;
CREATE TRIGGER IF NOT EXISTS accounting_key_subsidies_count BEFORE INSERT ON key_subsidies WHEN NOT EXISTS(SELECT 1 FROM key_subsidies WHERE owner=NEW.owner) AND (SELECT count(*) FROM key_subsidies)>=1024  BEGIN SELECT RAISE(ABORT,'accounting count capacity'); END;
